#!/usr/bin/env python3
"""Policz kolejną wersję integracji i wpisz ją do manifest.json.

Reguły (conventional commits, liczone z commitów od ostatniego tagu vX.Y.Z):
  - BREAKING CHANGE w treści lub `typ!: ...` w nagłówku -> major
  - `feat: ...` / `feat(scope): ...`                    -> minor
  - cokolwiek innego                                    -> patch

Jeśli tag dla bieżącej wersji z manifestu jeszcze nie istnieje, wydajemy tę
wersję bez bumpa (obsługuje pierwszy release oraz ręczne podbicie w manifeście).

Skrypt wypisuje na stdout (do wczytania przez workflow):
  VERSION=<nowa-wersja>
  CHANGED=<true|false>
"""
from __future__ import annotations

import json
import re
import subprocess
import sys

MANIFEST = "custom_components/powerpilot/manifest.json"

BANG_RE = re.compile(r"^[a-z]+(\([^)]+\))?!:", re.MULTILINE)
FEAT_RE = re.compile(r"^feat(\([^)]+\))?:", re.MULTILINE)
BREAKING_RE = re.compile(r"^BREAKING CHANGE", re.MULTILINE)


def git(*args: str) -> str:
    return subprocess.run(
        ["git", *args], capture_output=True, text=True, check=True
    ).stdout


def tag_exists(tag: str) -> bool:
    return (
        subprocess.run(
            ["git", "rev-parse", "-q", "--verify", f"refs/tags/{tag}"],
            capture_output=True,
        ).returncode
        == 0
    )


def bump_kind(log: str) -> str:
    if BREAKING_RE.search(log) or BANG_RE.search(log):
        return "major"
    if FEAT_RE.search(log):
        return "minor"
    return "patch"


def next_version(current: str, kind: str) -> str:
    major, minor, patch = (int(p) for p in current.split("."))
    if kind == "major":
        return f"{major + 1}.0.0"
    if kind == "minor":
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"

"""WebSocket API for the PowerPilot panel.

Exposes the full plan, feature status and a runtime event log to the custom
frontend panel, instead of overloading entity attributes.
"""

from __future__ import annotations

import voluptuous as vol
from homeassistant.components import websocket_api
from homeassistant.core import HomeAssistant, callback

from .const import DOMAIN


def _coordinator(hass: HomeAssistant):
    from .coordinator import PowerPilotCoordinator

    for value in hass.data.get(DOMAIN, {}).values():
        if isinstance(value, PowerPilotCoordinator):
            return value
    return None


@websocket_api.websocket_command({vol.Required("type"): "powerpilot/plan"})
@callback
def ws_plan(hass: HomeAssistant, connection, msg) -> None:
    coordinator = _coordinator(hass)
    plan = coordinator.data if coordinator else None
    connection.send_result(msg["id"], plan.as_dict() if plan else {})


@websocket_api.websocket_command({vol.Required("type"): "powerpilot/status"})
@callback
def ws_status(hass: HomeAssistant, connection, msg) -> None:
    coordinator = _coordinator(hass)
    connection.send_result(msg["id"], coordinator.get_status() if coordinator else {})


@websocket_api.websocket_command({vol.Required("type"): "powerpilot/log"})
@callback
def ws_log(hass: HomeAssistant, connection, msg) -> None:
    coordinator = _coordinator(hass)
    connection.send_result(
        msg["id"], {"events": coordinator.get_log() if coordinator else []}
    )


@websocket_api.websocket_command({vol.Required("type"): "powerpilot/profiles"})
@callback
def ws_profiles(hass: HomeAssistant, connection, msg) -> None:
    coordinator = _coordinator(hass)
    connection.send_result(msg["id"], coordinator.get_profiles() if coordinator else {})


@websocket_api.websocket_command(
    {
        vol.Required("type"): "powerpilot/series",
        vol.Optional("past_hours", default=24): int,
        vol.Optional("start"): str,
        vol.Optional("end"): str,
        vol.Optional("forecast_lead", default=0): int,
        vol.Optional("forecast_run_at"): str,
    }
)
@websocket_api.async_response
async def ws_series(hass: HomeAssistant, connection, msg) -> None:
    coordinator = _coordinator(hass)
    if not coordinator:
        connection.send_result(msg["id"], {"hours": []})
        return
    result = await coordinator.get_series(
        past_hours=int(msg.get("past_hours", 24)),
        start=msg.get("start"),
        end=msg.get("end"),
        forecast_lead=int(msg.get("forecast_lead", 0)),
        forecast_run_at=msg.get("forecast_run_at"),
    )
    connection.send_result(msg["id"], result)

def get_status(self) -> dict:
    """Feature/module status for the panel: what works, what's missing."""
    from .const import (
        CONF_BUY_PRICE_SENSOR,
        CONF_CONSUMPTION_SENSOR,
        CONF_PRADCAST_API_KEY,
        CONF_PRICE_SOURCE,
        CONF_SOC_SENSOR,
        INTEGRATION_VERSION,
        PRICE_SOURCE_PRADCAST,
    )

    plan = self.data
    price_source = self.config.get(CONF_PRICE_SOURCE)
    price_ok = bool(
        self.config.get(CONF_PRADCAST_API_KEY)
        if price_source == PRICE_SOURCE_PRADCAST
        else self.config.get(CONF_BUY_PRICE_SENSOR)
    )

    modules = []
    for module in self.registry.modules:
        modules.append(
            {
                "domain": module.domain,
                "error": module.last_error,
            }
        )

    checks = [
        {
            "key": "battery_soc",
            "label": "🔋 Sensor SoC ESS",
            "ok": bool(self.config.get(CONF_SOC_SENSOR)),
        },
        {
            "key": "prices",
            "label": f"Źródło cen ({price_source})",
            "ok": price_ok,
        },
        {
            "key": "consumption",
            "label": "Sensor zużycia",
            "ok": bool(self.config.get(CONF_CONSUMPTION_SENSOR)),
        },
        {
            "key": "tariff",
            "label": "Taryfa dystrybucyjna",
            "ok": bool(
                self.tariff.tariffs
                and tariff_for_day(self.tariff.tariffs, dt_util.now().date())
            ),
        },
    ]

    ev_summary = self.ev.plan_summary()
    ev_summary["control"] = self.ev_control()
    ev_summary["planned_hours"] = (
        [
            {"start": d.start.isoformat(), "kwh": round(d.ev_charge_kwh, 3)}
            for d in plan.decisions
            if d.ev_charge_kwh > 0
        ]
        if plan
        else []
    )

    return {
        "version": INTEGRATION_VERSION,
        "last_update": self.events[0]["time"] if self.events else None,
        "horizon_hours": len(plan.decisions) if plan else 0,
        "price_archive_hours": len(self.prices.archive),
        "consumption_days": self.consumption.base.observed_days,
        "consumption_devices": list(self.consumption.devices.keys()),
        "ev_enabled": self.ev.enabled,
        "ev": ev_summary,
        "modules": modules,
        "checks": checks,
    }

